use lg_cli::args::Command;
use lg_cli::commands::run;
use lg_cli::Settings;

#[test]
fn disc_l09() {
    let extrato = "data;descricao;valor\n2024-03-01;A UM;-1,00\n2024-03-31;B TRINTA E UM;-2,00\n2024-04-01;C ABRIL;-3,00\n";
    let cmd = Command::Query {
        category: None,
        from: Some("2024-03-01".into()),
        to: Some("2024-03-31".into()),
        text: None,
        limit: None,
    };
    let out = run(&cmd, &Settings::default(), &[("x.csv", extrato)], None).unwrap();
    assert!(out.contains("A UM"), "{out}");
    assert!(out.contains("B TRINTA E UM"), "{out}");
    assert!(!out.contains("C ABRIL"), "{out}");
}
